steps.body:
Fast order books often store each side as an array indexed by price level: `qty[i]` is the quantity resting `i` ticks above a base price. Adding and cancelling are O(1), but the best bid is the highest nonempty level. After a trade sweeps the top of the book, finding the next one means scanning down level by level, hundreds of steps on the hot path when the book is thin.

Keep one bit per level beside the array. With up to 64 levels, the best bid is `63 - __builtin_clzll(bits)` and the best ask is `__builtin_ctzll(bits)`. For 4096 levels, use 64 words of 64 bits, plus a **summary** word whose bit `w` says word `w` has any bit set. Level `L` is bit `L & 63` of word `L >> 6`:

```cpp harness
#include <bits/stdc++.h>

struct LevelBitmap {
    std::uint64_t words[64] = {};
    std::uint64_t summary = 0;

    {{code}}
};

int main() {
    LevelBitmap bids;
    bids.set(1000);
    bids.set(3005);
    std::cout << bids.highest() << '\n';
    return 0;
}
```

```cpp
void set(int level) {
    words[level >> 6] |= 1ULL << (level & 63);
    summary |= 1ULL << (level >> 6);
}

int highest() const {   // -1 when the side is empty
    if (summary == 0) {
        return -1;
    }
    const int w = 63 - __builtin_clzll(summary);
    return w * 64 + 63 - __builtin_clzll(words[w]);
}
```

Clearing a level clears its bit, and the summary bit too once that word reaches 0. Each operation touches at most two words, however empty the book is. A third level of summary would cover 2^18 price levels the same way.

example.code:
#include <cstdint>
#include <iostream>

struct LevelBitmap {  // 4096 price levels: 64 words of 64 bits
    std::uint64_t words[64] = {};
    std::uint64_t summary = 0;  // bit w set: words[w] != 0

    void set(int level) {
        words[level >> 6] |= 1ULL << (level & 63);
        summary |= 1ULL << (level >> 6);
    }

    void clear(int level) {
        const int w = level >> 6;
        words[w] &= ~(1ULL << (level & 63));
        if (words[w] == 0) {
            summary &= ~(1ULL << w);
        }
    }

    int highest() const {  // the best bid, or -1 when the side is empty
        if (summary == 0) {
            return -1;
        }
        const int w = 63 - __builtin_clzll(summary);
        return w * 64 + 63 - __builtin_clzll(words[w]);
    }
};

int qty[4096] = {};  // the book side itself: quantity at each level

int best_by_scan = 4095;  // the scan starts from the previous best bid

int highest_by_scan(long& steps) {
    for (int level = best_by_scan; level >= 0; --level) {
        ++steps;
        if (qty[level] > 0) {
            return level;
        }
    }
    return -1;
}

void report(const LevelBitmap& bits) {
    long steps = 0;
    const int scanned = highest_by_scan(steps);
    best_by_scan = scanned;
    std::cout << "best bid " << bits.highest() << ", scan says " << scanned << " after " << steps << " steps\n";
}

int main() {
    LevelBitmap bits;
    for (int level : {1000, 1500, 3000, 3001, 3002, 3005}) {
        qty[level] = 200;
        bits.set(level);
    }
    report(bits);
    for (int level : {3005, 3002, 3001, 3000}) {  // a trade sweeps the top four levels
        qty[level] = 0;
        bits.clear(level);
    }
    report(bits);
    qty[1500] = 0;
    bits.clear(1500);
    report(bits);
    qty[1000] = 0;
    bits.clear(1000);
    report(bits);
    return 0;
}

