// -O2
#include <cstddef>
#include <cstring>
#include <immintrin.h>
#include <iostream>
#include <vector>

void mids_scalar(const double* bid, const double* ask, double* mid, std::size_t n) {
    for (std::size_t i = 0; i < n; ++i) {
        mid[i] = (bid[i] + ask[i]) * 0.5;
    }
}

void mids_sse2(const double* bid, const double* ask, double* mid, std::size_t n) {
    const __m128d half = _mm_set1_pd(0.5);
    std::size_t i = 0;
    for (; i + 2 <= n; i += 2) {
        const __m128d sum = _mm_add_pd(_mm_loadu_pd(bid + i), _mm_loadu_pd(ask + i));
        _mm_storeu_pd(mid + i, _mm_mul_pd(sum, half));
    }
    mids_scalar(bid + i, ask + i, mid + i, n - i);  // the leftover tail
}

#pragma GCC push_options
#pragma GCC target("avx2")
void mids_avx2(const double* bid, const double* ask, double* mid, std::size_t n) {
    const __m256d half = _mm256_set1_pd(0.5);
    std::size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        const __m256d sum = _mm256_add_pd(_mm256_loadu_pd(bid + i), _mm256_loadu_pd(ask + i));
        _mm256_storeu_pd(mid + i, _mm256_mul_pd(sum, half));
    }
    for (; i < n; ++i) {
        mid[i] = (bid[i] + ask[i]) * 0.5;
    }
}
#pragma GCC pop_options

typedef double v4d __attribute__((vector_size(32)));  // portable: SSE2, AVX2, or NEON

void mids_portable(const double* bid, const double* ask, double* mid, std::size_t n) {
    std::size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        v4d b, a;
        std::memcpy(&b, bid + i, sizeof b);
        std::memcpy(&a, ask + i, sizeof a);
        const v4d m = (b + a) * 0.5;
        std::memcpy(mid + i, &m, sizeof m);
    }
    mids_scalar(bid + i, ask + i, mid + i, n - i);
}

int main() {
    const std::size_t n = 1003;
    std::vector<double> bid(n), ask(n), want(n), got(n);
    for (std::size_t i = 0; i < n; ++i) {
        bid[i] = (10000 + i % 97) / 100.0;
        ask[i] = (10001 + i % 97 + i % 3) / 100.0;
    }
    mids_scalar(bid.data(), ask.data(), want.data(), n);
    const auto check = [&](const char* name) {
        const bool same = std::memcmp(got.data(), want.data(), n * sizeof(double)) == 0;
        std::cout << name << " == scalar: " << (same ? "yes" : "no") << '\n';
    };
    mids_sse2(bid.data(), ask.data(), got.data(), n);
    check("sse2");
    if (__builtin_cpu_supports("avx2")) {
        mids_avx2(bid.data(), ask.data(), got.data(), n);
    } else {
        mids_sse2(bid.data(), ask.data(), got.data(), n);  // the fallback without AVX2
    }
    check("avx2 where the CPU has it");
    mids_portable(bid.data(), ask.data(), got.data(), n);
    check("vector_size");
    return 0;
}

