// -O2
#include <cstddef>
#include <cstring>
#include <immintrin.h>
#include <iomanip>
#include <iostream>
#include <vector>

struct Quotes {  // struct of arrays
    std::vector<double> bid, ask, bid_sz, ask_sz;
};

void micro_scalar(const Quotes& q, double* out, std::size_t from, std::size_t n) {
    for (std::size_t i = from; i < n; ++i) {
        out[i] = (q.bid[i] * q.ask_sz[i] + q.ask[i] * q.bid_sz[i]) / (q.bid_sz[i] + q.ask_sz[i]);
    }
}

#pragma GCC push_options
#pragma GCC target("avx2")
void micro_avx2(const Quotes& q, double* out, std::size_t n) {
    std::size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        const __m256d b = _mm256_loadu_pd(q.bid.data() + i);
        const __m256d a = _mm256_loadu_pd(q.ask.data() + i);
        const __m256d bs = _mm256_loadu_pd(q.bid_sz.data() + i);
        const __m256d as = _mm256_loadu_pd(q.ask_sz.data() + i);
        const __m256d top = _mm256_add_pd(_mm256_mul_pd(b, as), _mm256_mul_pd(a, bs));
        _mm256_storeu_pd(out + i, _mm256_div_pd(top, _mm256_add_pd(bs, as)));
    }
    micro_scalar(q, out, i, n);  // the tail
}
#pragma GCC pop_options

int main() {
    std::size_t n = 0;
    std::cin >> n;
    Quotes q;
    for (std::size_t i = 0; i < n; ++i) {
        q.bid.push_back((10000 + i % 89) / 100.0);
        q.ask.push_back((10002 + i % 89) / 100.0);
        q.bid_sz.push_back(100.0 + i * 37 % 900);
        q.ask_sz.push_back(100.0 + i * 53 % 700);
    }
    std::vector<double> want(n), got(n);
    micro_scalar(q, want.data(), 0, n);
    if (__builtin_cpu_supports("avx2")) {
        micro_avx2(q, got.data(), n);
    } else {
        micro_scalar(q, got.data(), 0, n);
    }
    const bool same = std::memcmp(got.data(), want.data(), n * sizeof(double)) == 0;
    double sum = 0.0;
    for (double m : got) {
        sum += m;
    }
    std::cout << "avx2 == scalar: " << (same ? "yes" : "no") << '\n';
    std::cout << std::fixed << std::setprecision(6) << "sum of microprices: " << sum << '\n';
    return 0;
}
